// Ballistic player ability. Swept substeps reuse the same solid/enemy geometry as the shuriken.
export class KageBombs {
 constructor(scene,config,{world,origin,aim,units,missiles,hit,velocity=()=>new THREE.Vector3(),redirect=()=>null,onThrow=()=>{},canThrow=()=>true,onDetonate=null,expireDetonates=false,variant='explosive'}){Object.assign(this,{scene,config,world,origin,aim,units,missiles,hit,velocity,redirect,onThrow,canThrow,onDetonate,expireDetonates});this.group=new THREE.Group();scene.add(this.group);this.group.name=variant==='smoke'?'Kage smoke projectiles':'Kage explosive bombs';this.geometry=variant==='smoke'?new THREE.CylinderGeometry(config.radius*.75,config.radius*.8,config.radius*2,8):new THREE.IcosahedronGeometry(config.radius,1);this.material=new THREE.MeshStandardMaterial({color:variant==='smoke'?'#68728c':'#243040',metalness:.7,roughness:.35});this.glowMaterial=new THREE.MeshBasicMaterial({color:'#c8a4ff',transparent:true,opacity:.32,depthWrite:false,toneMapped:false});this.ringGeometry=new THREE.TorusGeometry(config.radius*1.03,.045,4,14);this.ringMaterial=new THREE.MeshBasicMaterial({color:'#ba7fff',toneMapped:false});this.explosions=onDetonate?null:new MissileExplosions(scene);this.reset();}
 reset(){for(const b of this.bombs||[])this.group.remove(b.mesh);this.bombs=[];this.cooldown=0;this.throws=this.bounces=this.detonations=this.totalDamage=0;this.explosions?.reset();}
 throw({aim=null}={}){const c=this.config;if(!this.canThrow()||this.cooldown>0||this.bombs.length>=c.maxActive)return false;const position=this.origin().clone(),direction=(aim||this.aim()).clone().sub(position).normalize(),velocity=direction.multiplyScalar(c.speed).add(new THREE.Vector3(0,c.lift,0)).addScaledVector(new THREE.Vector3().copy(this.velocity()),c.inheritVelocity),mesh=new THREE.Group();mesh.add(new THREE.Mesh(this.geometry,this.material));const glow=new THREE.Mesh(this.geometry,this.glowMaterial);glow.scale.setScalar(1.35);mesh.add(glow);for(const angle of[0,Math.PI/2]){const ring=new THREE.Mesh(this.ringGeometry,this.ringMaterial);ring.rotation.x=angle;mesh.add(ring);}mesh.position.copy(position);this.group.add(mesh);this.bombs.push({mesh,position,velocity,age:0,dir:velocity.clone().normalize(),speed:velocity.length(),owner:'kage'});this.cooldown=c.cooldown;this.throws++;this.onThrow();return true;}
 clearBlast(a,b){const hit=this.world.flightSolid(a,b,0,true);return !hit||hit.t>.98;}
 explode(b,direct){const c=this.config,p=b.position;this.detonations++;if(this.onDetonate){this.onDetonate(b,direct);return;}this.explosions.burst(p,{scale:1.05});const done=new Set();for(const unit of this.units()){if(!unit.alive||unit.dashPhased||done.has(unit))continue;done.add(unit);const near=this.world.nearest(unit,p);if(!near||near.distance>c.blastRadius&&unit!==direct?.unit)continue;const isDirect=unit===direct?.unit;if(!isDirect&&!this.clearBlast(p,near.point))continue;const power=isDirect?c.damage:c.damage*(1-c.falloff*near.distance/c.blastRadius),result=this.hit({kind:'unit',unit,part:isDirect?direct.part:near.part,point:isDirect?direct.point:near.point},power,'ninja-bomb');this.totalDamage+=result?.damage||0;}for(const missile of this.missiles()){if(!missile.alive)continue;const point=new THREE.Vector3().copy(missile.position);if(missile!==direct?.missile&&(point.distanceTo(p)>c.blastRadius||!this.clearBlast(p,point)))continue;this.hit({kind:'missile',missile,point},c.damage,'ninja-bomb');}}
 update(dt){const c=this.config;this.cooldown=Math.max(0,this.cooldown-dt);this.explosions?.update(dt);for(const b of [...this.bombs]){let dead=false;const steps=Math.max(1,Math.ceil(dt/c.maxStep)),h=dt/steps;for(let i=0;i<steps&&!dead;i++){b.age+=h;if(b.age>=c.lifetime){if(this.expireDetonates)this.explode(b,null);dead=true;break;}b.velocity.y-=c.gravity*h;const end=b.position.clone().addScaledVector(b.velocity,h);b.speed=b.velocity.length();b.dir.copy(b.velocity).normalize();const transit=this.redirect(b,b.position,end);if(transit){b.position.copy(transit.position);b.velocity.copy(transit.direction).multiplyScalar(b.speed);continue;}const solid=this.world.flightSolid(b.position,end,c.radius,true),enemy=this.world.enemies(b.position,end,c.radius)[0],threat=this.world.traceThreat?.(b.position,end,c.radius),target=threat?.missile?threat:enemy;let contact=enemy;if(target&&(!contact||target.t<contact.t))contact=target;if(contact&&(!solid||contact.t<=solid.t+1e-6)){b.position.copy(contact.point);this.explode(b,contact);dead=true;break;}if(solid){b.position.copy(solid.point);const n=this.world.normal(solid),incoming=b.velocity.dot(n);b.position.addScaledVector(n,c.skin);if(incoming<0){const normal=n.clone().multiplyScalar(incoming),tangent=b.velocity.clone().sub(normal).multiplyScalar(c.friction);b.velocity.copy(tangent).addScaledVector(normal,-c.restitution);}this.bounces++;}else b.position.copy(end);}b.mesh.position.copy(b.position);b.mesh.rotation.x+=dt*8;b.mesh.rotation.z+=dt*6;if(dead){this.group.remove(b.mesh);this.bombs.splice(this.bombs.indexOf(b),1);}}}
 diagnostics(){return{cooldown:this.cooldown,throws:this.throws,bounces:this.bounces,detonations:this.detonations,damage:this.totalDamage,active:this.bombs.length,bombs:this.bombs.map(b=>({position:b.position.toArray(),velocity:b.velocity.toArray(),age:b.age})),explosions:this.explosions?.diagnostics()||null};}
}
